export type PaymentPagesCheckoutSessionAdaptivePricing = {
  /** If enabled, Adaptive Pricing is available on [eligible sessions](https://docs.stripe.com/payments/currencies/localize-prices/adaptive-pricing?payment-ui=stripe-hosted#restrictions). */
  enabled: boolean;
};

export type PaymentPagesCheckoutSessionAfterExpirationRecovery = {
  /** Enables user redeemable promotion codes on the recovered Checkout Sessions. Defaults to `false` */
  allow_promotion_codes: boolean;
  /**
   * If `true`, a recovery url will be generated to recover this Checkout Session if it
   * expires before a transaction is completed. It will be attached to the
   * Checkout Session object upon expiration.
   */
  enabled: boolean;
  /**
   * The timestamp at which the recovery URL will expire.
   *
   * @format unix-time
   */
  expires_at?: number | null;
  /** URL that creates a new Checkout Session when clicked that is a copy of this expired Checkout Session */
  url?: string | null;
};

export type PaymentPagesCheckoutSessionAfterExpiration = {
  recovery?: PaymentPagesCheckoutSessionAfterExpirationRecovery;
};

export type PaymentPagesCheckoutSessionBrandingSettingsIcon = {
  /** The ID of a [File upload](https://stripe.com/docs/api/files) representing the icon. Purpose must be `business_icon`. Required if `type` is `file` and disallowed otherwise. */
  file?: string;
  type: "file" | "url";
  /** The URL of the image. Present when `type` is `url`. */
  url?: string;
};

export type PaymentPagesCheckoutSessionBrandingSettingsLogo = {
  /** The ID of a [File upload](https://stripe.com/docs/api/files) representing the logo. Purpose must be `business_logo`. Required if `type` is `file` and disallowed otherwise. */
  file?: string;
  type: "file" | "url";
  /** The URL of the image. Present when `type` is `url`. */
  url?: string;
};

export type PaymentPagesCheckoutSessionBrandingSettings = {
  /** A hex color value starting with `#` representing the background color for the Checkout Session. */
  background_color: string;
  border_style: "pill" | "rectangular" | "rounded";
  /** A hex color value starting with `#` representing the button color for the Checkout Session. */
  button_color: string;
  /** The display name shown on the Checkout Session. */
  display_name: string;
  /** The font family for the Checkout Session. Must be one of the [supported font families](https://docs.stripe.com/payments/checkout/customization/appearance?payment-ui=stripe-hosted#font-compatibility). */
  font_family: string;
  icon?: PaymentPagesCheckoutSessionBrandingSettingsIcon;
  logo?: PaymentPagesCheckoutSessionBrandingSettingsLogo;
};

export type PaymentPagesCheckoutSessionBusinessName = {
  /** Indicates whether business name collection is enabled for the session */
  enabled: boolean;
  /** Whether the customer is required to complete the field before completing the Checkout Session. Defaults to `false`. */
  optional: boolean;
};

export type PaymentPagesCheckoutSessionCheckoutAddressDetails = {
  address: Address;
  /** Customer name. */
  name: string;
};

export type PaymentPagesCheckoutSessionCollectedInformation = {
  /** Customer’s business name for this Checkout Session */
  business_name?: string | null;
  /** Customer’s individual name for this Checkout Session */
  individual_name?: string | null;
  shipping_details?: PaymentPagesCheckoutSessionCheckoutAddressDetails;
};

export type PaymentPagesCheckoutSessionConsent = {
  promotions?: "opt_in" | "opt_out";
  terms_of_service?: "accepted";
};

export type PaymentPagesCheckoutSessionCurrencyConversion = {
  /** Total of all items in source currency before discounts or taxes are applied. */
  amount_subtotal: number;
  /** Total of all items in source currency after discounts and taxes are applied. */
  amount_total: number;
  /**
   * Exchange rate used to convert source currency amounts to customer currency amounts
   *
   * @format decimal
   */
  fx_rate: string;
  /** Creation currency of the CheckoutSession before localization */
  source_currency: string;
};

export type PaymentPagesCheckoutSessionCustomFieldsLabel = {
  /** Custom text for the label, displayed to the customer. Up to 50 characters. */
  custom?: string | null;
  type: "custom";
};

export type PaymentPagesCheckoutSessionCustomFieldsNumeric = {
  /** The value that will pre-fill the field on the payment page. */
  default_value?: string | null;
  /** The maximum character length constraint for the customer's input. */
  maximum_length?: number | null;
  /** The minimum character length requirement for the customer's input. */
  minimum_length?: number | null;
  /** The value entered by the customer, containing only digits. */
  value?: string | null;
};

export type PaymentPagesCheckoutSessionCustomFieldsOption = {
  /** The label for the option, displayed to the customer. Up to 100 characters. */
  label: string;
  /** The value for this option, not displayed to the customer, used by your integration to reconcile the option selected by the customer. Must be unique to this option, alphanumeric, and up to 100 characters. */
  value: string;
};

export type PaymentPagesCheckoutSessionCustomFieldsDropdown = {
  /** The value that will pre-fill on the payment page. */
  default_value?: string | null;
  /** The options available for the customer to select. Up to 200 options allowed. */
  options: PaymentPagesCheckoutSessionCustomFieldsOption[];
  /** The option selected by the customer. This will be the `value` for the option. */
  value?: string | null;
};

export type PaymentPagesCheckoutSessionCustomFieldsText = {
  /** The value that will pre-fill the field on the payment page. */
  default_value?: string | null;
  /** The maximum character length constraint for the customer's input. */
  maximum_length?: number | null;
  /** The minimum character length requirement for the customer's input. */
  minimum_length?: number | null;
  /** The value entered by the customer. */
  value?: string | null;
};

export type PaymentPagesCheckoutSessionCustomFields = {
  dropdown?: PaymentPagesCheckoutSessionCustomFieldsDropdown;
  /** String of your choice that your integration can use to reconcile this field. Must be unique to this field, alphanumeric, and up to 200 characters. */
  key: string;
  label: PaymentPagesCheckoutSessionCustomFieldsLabel;
  numeric?: PaymentPagesCheckoutSessionCustomFieldsNumeric;
  /** Whether the customer is required to complete the field before completing the Checkout Session. Defaults to `false`. */
  optional: boolean;
  text?: PaymentPagesCheckoutSessionCustomFieldsText;
  type: "dropdown" | "numeric" | "text";
};

export type PaymentPagesCheckoutSessionCustomTextPosition = {
  /** Text may be up to 1200 characters in length. */
  message: string;
};

export type PaymentPagesCheckoutSessionCustomText = {
  after_submit?: PaymentPagesCheckoutSessionCustomTextPosition;
  shipping_address?: PaymentPagesCheckoutSessionCustomTextPosition;
  submit?: PaymentPagesCheckoutSessionCustomTextPosition;
  terms_of_service_acceptance?: PaymentPagesCheckoutSessionCustomTextPosition;
};

export type PaymentPagesCheckoutSessionIndividualName = {
  /** Indicates whether individual name collection is enabled for the session */
  enabled: boolean;
  /** Whether the customer is required to complete the field before completing the Checkout Session. Defaults to `false`. */
  optional: boolean;
};

export type PaymentPagesCheckoutSessionNameCollection = {
  business?: PaymentPagesCheckoutSessionBusinessName;
  individual?: PaymentPagesCheckoutSessionIndividualName;
};

export type PaymentPagesCheckoutSessionOptionalItemAdjustableQuantity = {
  /** Set to true if the quantity can be adjusted to any non-negative integer. */
  enabled: boolean;
  /** The maximum quantity of this item the customer can purchase. By default this value is 99. You can specify a value up to 999999. */
  maximum?: number | null;
  /** The minimum quantity of this item the customer must purchase, if they choose to purchase it. Because this item is optional, the customer will always be able to remove it from their order, even if the `minimum` configured here is greater than 0. By default this value is 0. */
  minimum?: number | null;
};

export type PaymentPagesCheckoutSessionOptionalItem = {
  adjustable_quantity?: PaymentPagesCheckoutSessionOptionalItemAdjustableQuantity;
  price: string;
  quantity: number;
};

