  cancel_url?: string | null;
  /**
   * A unique string to reference the Checkout Session. This can be a
   * customer ID, a cart ID, or similar, and can be used to reconcile the
   * Session with your internal systems.
   */
  client_reference_id?: string | null;
  /**
   * The client secret of your Checkout Session. Applies to Checkout Sessions with `ui_mode: embedded` or `ui_mode: custom`. For `ui_mode: embedded`, the client secret is to be used when initializing Stripe.js embedded checkout.
   *  For `ui_mode: custom`, use the client secret with [initCheckout](https://stripe.com/docs/js/custom_checkout/init) on your front end.
   */
  client_secret?: string | null;
  collected_information?: PaymentPagesCheckoutSessionCollectedInformation;
  consent?: PaymentPagesCheckoutSessionConsent;
  consent_collection?: PaymentPagesCheckoutSessionConsentCollection;
  /**
   * Time at which the object was created. Measured in seconds since the Unix epoch.
   *
   * @format unix-time
   */
  created: number;
  /**
   * Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Must be a [supported currency](https://stripe.com/docs/currencies).
   *
   * @format currency
   */
  currency?: string | null;
  currency_conversion?: PaymentPagesCheckoutSessionCurrencyConversion;
  /** Collect additional information from your customer using custom fields. Up to 3 fields are supported. */
  custom_fields: PaymentPagesCheckoutSessionCustomFields[];
  custom_text: PaymentPagesCheckoutSessionCustomText;
  customer?: string | Customer | DeletedCustomer;
  customer_creation?: "always" | "if_required";
