export const IssuingCardWalletsSchema: z.ZodType<IssuingCardWallets> = z.object({
  apple_pay: IssuingCardApplePaySchema,
  google_pay: IssuingCardGooglePaySchema,
  primary_account_identifier: z.string().max(5000).nullable().optional(),
});

export const IssuingCardholderAddressSchema: z.ZodType<IssuingCardholderAddress> = z.object({
  address: AddressSchema,
});

export const IssuingCardholderCompanySchema: z.ZodType<IssuingCardholderCompany> = z.object({
  tax_id_provided: z.boolean(),
});

export const IssuingCardholderIndividualDobSchema: z.ZodType<IssuingCardholderIndividualDob> = z.object({
  day: z.number().int().nullable().optional(),
  month: z.number().int().nullable().optional(),
  year: z.number().int().nullable().optional(),
});

export const IssuingCardholderRequirementsSchema: z.ZodType<IssuingCardholderRequirements> = z.object({
  disabled_reason: z.enum(["listed", "rejected.listed", "requirements.past_due", "under_review"]).optional(),
  past_due: z.array(
    z.enum([
      "company.tax_id",
      "individual.card_issuing.user_terms_acceptance.date",
      "individual.card_issuing.user_terms_acceptance.ip",
      "individual.dob.day",
      "individual.dob.month",
      "individual.dob.year",
      "individual.first_name",
      "individual.last_name",
      "individual.verification.document",
    ]),
  ).nullable().optional(),
});

