/**
 * Retrieve account
 *
 * <p>Retrieves the details of an account.</p>
 */
export const getAccount = (config: OpenAPIClientConfig, request: {
  query?: {
    /** Specifies which fields in the response should be expanded. */
    expand?: string[];
  };
  body: "WARN: application/json is the only supported content type";
}): OpenAPIResponsePromise<
  OpenAPIResponses<{
    /** Successful response. */
    200: {
      body: Account;
    };
    /** Error response. */
    "default": {
      body: Error;
    };
  }>
> =>
  openAPIFetch(
    config,
    {
      path: "/v1/account",
      method: "get",
      parameters: [{ "name": "expand", "location": "query", "style": "deepObject", "explode": true }],
      requestSchema: z.object({
        query: z.object({
          expand: z.array(z.string().max(5000)).optional(),
        }).optional(),
      }),
      responseSchema: {
        200: z.object({ body: z.lazy((): z.ZodType<Account> => AccountSchema) }),
        "default": z.object({ body: z.lazy((): z.ZodType<Error> => ErrorSchema) }),
      },
    },
    request,
  ) as any;

