/**
 * List all connected accounts
 *
 * <p>Returns a list of accounts connected to your platform via <a href="/docs/connect">Connect</a>. If you’re not a platform, the list is empty.</p>
 */
export const getAccounts = (config: OpenAPIClientConfig, request: {
  query?: {
    /** Only return connected accounts that were created during the given date interval. */
    created?: {
      gt?: number;
      gte?: number;
      lt?: number;
      lte?: number;
    } | number;
    /** A cursor for use in pagination. `ending_before` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, starting with `obj_bar`, your subsequent call can include `ending_before=obj_bar` in order to fetch the previous page of the list. */
    ending_before?: string;
    /** Specifies which fields in the response should be expanded. */
    expand?: string[];
    /** A limit on the number of objects to be returned. Limit can range between 1 and 100, and the default is 10. */
    limit?: number;
    /** A cursor for use in pagination. `starting_after` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, ending with `obj_foo`, your subsequent call can include `starting_after=obj_foo` in order to fetch the next page of the list. */
    starting_after?: string;
  };
  body: "WARN: application/json is the only supported content type";
}): OpenAPIResponsePromise<
  OpenAPIResponses<{
    /** Successful response. */
    200: {
      body: {
        data: Account[];
        /** True if this list has another page of items after this one that can be fetched. */
        has_more: boolean;
        object: "list";
        /** The URL where this list can be accessed. */
        url: string;
      };
    };
    /** Error response. */
    "default": {
      body: Error;
    };
  }>
> =>
  openAPIFetch(
    config,
    {
      path: "/v1/accounts",
      method: "get",
      parameters: [{ "name": "created", "location": "query", "style": "deepObject", "explode": true }, {
        "name": "expand",
        "location": "query",
        "style": "deepObject",
        "explode": true,
      }],
      requestSchema: z.object({
        query: z.object({
          created: z.union([
            z.object({
              gt: z.number().int().optional(),
              gte: z.number().int().optional(),
              lt: z.number().int().optional(),
              lte: z.number().int().optional(),
            }),
            z.number().int(),
          ]).optional(),
          ending_before: z.string().optional(),
          expand: z.array(z.string().max(5000)).optional(),
          limit: z.number().int().optional(),
          starting_after: z.string().optional(),
        }).optional(),
      }),
      responseSchema: {
        200: z.object({
          body: z.object({
            data: z.array(z.lazy((): z.ZodType<Account> => AccountSchema)),
            has_more: z.boolean(),
            object: z.enum(["list"]),
            url: z.string().regex(new RegExp("^/v1/accounts")).max(5000),
          }),
        }),
        "default": z.object({ body: z.lazy((): z.ZodType<Error> => ErrorSchema) }),
      },
    },
    request,
  ) as any;

/**
 * <p>With <a href="/docs/connect">Connect</a>, you can create Stripe accounts for your users.
 * To do this, you’ll first need to <a href="https://dashboard.stripe.com/account/applications/settings">register your platform</a>.</p>
 *
 * <p>If you’ve already collected information for your connected accounts, you <a href="/docs/connect/best-practices#onboarding">can prefill that information</a> when
 * creating the account. Connect Onboarding won’t ask for the prefilled information during account onboarding.
 * You can prefill any information on the account.</p>
 */
