/**
 * List all account capabilities
 *
 * <p>Returns a list of capabilities associated with the account. The capabilities are returned sorted by creation date, with the most recent capability appearing first.</p>
 */
export const getAccountsAccountCapabilities = (config: OpenAPIClientConfig, request: {
  path: {
    account: string;
  };
  query?: {
    /** Specifies which fields in the response should be expanded. */
    expand?: string[];
  };
  body: "WARN: application/json is the only supported content type";
}): OpenAPIResponsePromise<
  OpenAPIResponses<{
    /** Successful response. */
    200: {
      body: {
        data: Capability[];
        /** True if this list has another page of items after this one that can be fetched. */
        has_more: boolean;
        object: "list";
        /** The URL where this list can be accessed. */
        url: string;
      };
    };
    /** Error response. */
    "default": {
      body: Error;
    };
  }>
> =>
  openAPIFetch(
    config,
    {
      path: "/v1/accounts/{account}/capabilities",
      method: "get",
      parameters: [{ "name": "expand", "location": "query", "style": "deepObject", "explode": true }],
      requestSchema: z.object({
        path: z.object({
          account: z.string().max(5000),
        }),
        query: z.object({
          expand: z.array(z.string().max(5000)).optional(),
        }).optional(),
      }),
      responseSchema: {
        200: z.object({
          body: z.object({
            data: z.array(z.lazy((): z.ZodType<Capability> => CapabilitySchema)),
            has_more: z.boolean(),
            object: z.enum(["list"]),
            url: z.string().max(5000),
          }),
        }),
        "default": z.object({ body: z.lazy((): z.ZodType<Error> => ErrorSchema) }),
      },
    },
    request,
  ) as any;

